function gridCss(o){
  o=o||{};
  var cols=o.cols||1, rows=o.rows||1, colU=o.colUnit||'1fr', rowU=o.rowUnit||'auto', gap=(o.gap==null?8:o.gap);
  function rep(nn,u){ var a=[]; for(var i=0;i<nn;i++) a.push(u); return a.join(' '); }
  return 'display:grid;grid-template-columns:'+rep(cols,colU)+';grid-template-rows:'+rep(rows,rowU)+';gap:'+gap+'px;';
}
function gridAreas(names, cols){
  var rows=[]; for(var i=0;i<names.length;i+=cols) rows.push(names.slice(i,i+cols).join(' '));
  return 'grid-template-areas:"'+rows.join('" "')+'";';
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { gridCss:gridCss, gridAreas:gridAreas }; }
if (typeof window !== 'undefined') { window.GridForgePure = { gridCss:gridCss, gridAreas:gridAreas }; }
